'use strict';
// Local, unranked progression. Never used as proof of a purchase or a multiplayer result.
const Progression=(()=>{
const KEY='runroad-passport-v1';
const paints=[
{id:'stock',name:'Factory finish',color:'#f16b35',accent:'#ffc28a',level:1},
{id:'sunset',name:'Sunset Rally',color:'#ffb347',accent:'#fff1bd',level:2},
{id:'signal',name:'Signal Blue',color:'#5ed6e4',accent:'#f2fbff',level:4},
{id:'violet',name:'Midnight Violet',color:'#b6a0ed',accent:'#f5ddff',level:7},
{id:'coast',name:'Coastline',color:'#5ee3b5',accent:'#fff0a8',cost:160},
{id:'rally',name:'Homebound Rally',color:'#e75f68',accent:'#fff1d7',cost:300}
];
const badges=[{id:'first',name:'First road home',key:'wins',goal:1},{id:'clean',name:'Steady hands',key:'clean',goal:5},{id:'near',name:'Thread the needle',key:'near',goal:50},{id:'drift',name:'Sideways soul',key:'drift',goal:120},{id:'wreck',name:'Let them crash',key:'wrecks',goal:100},{id:'chain',name:'In the flow',key:'peak',goal:5},{id:'nitro',name:'Perfect timing',key:'perfects',goal:20}];
const contracts=[{id:'wins',name:'Bring it home',text:'Complete 2 campaign escapes',goal:2,credits:180,chips:25},{id:'near',name:'Thread the heat',text:'Make 6 close calls',goal:6,credits:150,chips:25},{id:'drift',name:'Find your flow',text:'Drift for 15 seconds in total',goal:15,credits:160,chips:25},{id:'wrecks',name:'Outsmart pursuit',text:'Wreck 8 police cars',goal:8,credits:170,chips:25},{id:'seconds',name:'Road time',text:'Drive for 90 seconds in total',goal:90,credits:140,chips:20},{id:'peak',name:'Chain reaction',text:'Reach a style chain of 4',goal:4,credits:200,chips:30},{id:'perfects',name:'Perfect timing',text:'Land 3 Perfect Nitro boosts',goal:3,credits:180,chips:25}];
const empty=()=>({xp:0,chips:0,owned:['stock'],equipped:'stock',badges:[],totals:{wins:0,clean:0,near:0,drift:0,wrecks:0,peak:0,seconds:0,perfects:0},day:'',daily:{},claimed:[]});
const integer=(n,max=100000000)=>Number.isFinite(n)?Math.max(0,Math.min(max,Math.floor(n))):0;
let data=empty(),run=null,receipt=null,note='',preview='sunset',catalog=null;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&typeof s==='object'){
 data.xp=integer(s.xp);data.chips=integer(s.chips,1000000);data.owned=Array.isArray(s.owned)?s.owned.filter(id=>paints.some(p=>p.id===id)):['stock'];if(!data.owned.includes('stock'))data.owned.push('stock');
 data.equipped=data.owned.includes(s.equipped)?s.equipped:'stock';data.badges=Array.isArray(s.badges)?s.badges.filter(id=>badges.some(b=>b.id===id)):[];
 for(const k of Object.keys(data.totals))data.totals[k]=integer(s.totals?.[k]);
 if(/^\d{4}-\d{2}-\d{2}$/.test(s.day||'')&&Number.isFinite(Date.parse(s.day+'T00:00:00Z'))){data.day=s.day;for(const c of contracts)data.daily[c.id]=integer(s.daily?.[c.id]);data.claimed=Array.isArray(s.claimed)?s.claimed.filter(id=>contracts.some(c=>c.id===id)):[]}
}}catch{}
let equippedPaint=paints.find(p=>p.id===data.equipped)||paints[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{note='Storage unavailable. Passport rewards last for this session.';return false}}
function today(){return new Date().toISOString().slice(0,10)}
function day(){const now=today();if(!data.day||now>data.day){data.day=now;data.daily={};data.claimed=[];save()}return data.day}
function daily(){const date=day(),seed=Math.floor(Date.parse(date+'T00:00:00Z')/86400000),offset=((seed%contracts.length)+contracts.length)%contracts.length;return [0,2,4].map(i=>contracts[(offset+i)%contracts.length])}
function level(){return Math.floor(Math.sqrt(data.xp/120))+1}
function addXp(n){data.xp=integer(data.xp+integer(n));for(const p of paints)if(p.level&&level()>=p.level&&!data.owned.includes(p.id))data.owned.push(p.id)}
function solo(){return !(typeof R!=='undefined'&&R.active)&&!(typeof V!=='undefined'&&V.active)}
function begin(){receipt=null;run={done:false,eligible:solo()};day()}
function finish(won,stats){
 if(!run||run.done||!run.eligible||!solo())return null;run.done=true;
 const seconds=Math.min(180,Math.max(0,Number(stats.seconds)||0));if(seconds<10&&!won)return null;
 day();const s={wins:won?1:0,clean:won&&stats.hull>=.75?1:0,near:integer(stats.near,200),drift:Math.min(180,Math.max(0,Number(stats.drift)||0)),wrecks:integer(stats.kills,200),peak:integer(stats.peak,5),perfects:integer(stats.perfects,50),seconds};
 const completed=[];
 for(const k of Object.keys(s)){if(k==='peak'){data.totals[k]=Math.max(data.totals[k],s[k]);data.daily[k]=Math.max(data.daily[k]||0,s[k])}else{data.totals[k]=Math.min(100000000,data.totals[k]+s[k]);data.daily[k]=Math.min(100000000,(data.daily[k]||0)+s[k])}}
 const xp=Math.min(400,Math.floor(seconds/2)+s.wins*80+s.near*4+Math.floor(s.drift*2)+s.wrecks*8+s.peak*8+s.clean*30+s.perfects*12);
 addXp(xp);const chips=s.wins?8:0;data.chips=integer(data.chips+chips,1000000);
 for(const b of badges)if(data.totals[b.key]>=b.goal&&!data.badges.includes(b.id)){data.badges.push(b.id);data.chips=integer(data.chips+15,1000000);addXp(50);completed.push(b.name)}
 receipt={xp:xp+completed.length*50,chips:chips+completed.length*15,clean:!!s.clean,badges:completed,level:level()};save();return receipt;
}
function claim(id){const c=daily().find(c=>c.id===id);if(!c||data.claimed.includes(id)||(data.daily[id]||0)<c.goal)return false;data.claimed.push(id);data.chips=integer(data.chips+c.chips,1000000);addXp(60);C.awardCredits(c.credits);save();note=`Contract collected · +${c.credits} credits · +${c.chips} style tokens · +60 XP`;return true}
function equip(id){if(!data.owned.includes(id))return false;data.equipped=id;equippedPaint=paints.find(p=>p.id===id);save();note='Livery equipped. Same car. Same performance.';return true}
function buy(id){const p=paints.find(p=>p.id===id);if(!p?.cost||data.owned.includes(id)||data.chips<p.cost)return false;data.chips-=p.cost;data.owned.push(id);data.equipped=id;equippedPaint=p;save();note='Livery unlocked with earned style tokens.';return true}
function xpBar(){const l=level(),low=(l-1)**2*120,high=l*l*120;return{l,low,high,progress:data.xp-low,total:high-low}}
function home(){const x=xpBar(),ready=daily().filter(c=>!data.claimed.includes(c.id)&&(data.daily[c.id]||0)>=c.goal).length;return `<div class="passport-home"><button data-pass="journal"><span class="driver-number">${x.l}</span><span><small>DRIVER PASSPORT</small><b>${ready?ready+' CONTRACT'+(ready>1?'S':'')+' READY':'THE NEXT ROAD IS YOURS'}</b><span class="passport-track"><i style="width:${x.progress/x.total*100}%"></i></span><small>${x.progress} / ${x.total} XP · ${data.chips} STYLE TOKENS</small></span><strong>↗</strong></button><button data-pass="style"><span class="passport-paint" style="--paint:${paints.find(p=>p.id===data.equipped).color}"></span><span><small>MAKE IT YOURS</small><b>STYLE STUDIO</b><small>Earn liveries. Keep every advantage fair.</small></span><strong>↗</strong></button></div>`}
function journal(){const x=xpBar();return `<div class="passport-hero"><div><div class="eyebrow">EVERY ESCAPE LEAVES A MARK</div><h3>YOUR NEXT<br><em>GREAT GETAWAY.</em></h3><p>Small goals. Better driving. A garage that feels like yours.</p></div><div class="passport-rank"><small>DRIVER LEVEL</small><strong>${x.l}</strong><progress max="${x.total}" value="${x.progress}" aria-label="Driver experience"></progress><span>${x.progress} / ${x.total} XP</span><b>${data.chips} ◇ STYLE TOKENS</b></div></div><div class="section-title"><div><h3>TODAY’S THREE ROADS.</h3><p>${data.day} · Refreshes at 00:00 UTC. No streak to lose. No energy to refill. Perfect Nitro: tap boost at 85–95% charge.</p></div><span class="pill">SOLO CAMPAIGN</span></div><div class="contract-grid">${daily().map((c,i)=>{const progress=Math.min(c.goal,data.daily[c.id]||0),claimed=data.claimed.includes(c.id),ready=progress>=c.goal;return `<article class="contract-card ${ready?'complete':''}"><small>CONTRACT 0${i+1} ${claimed?'· COLLECTED':ready?'· READY':''}</small><h3>${c.name}</h3><p>${c.text}</p><div class="contract-progress"><b>${Math.floor(progress)} / ${c.goal}</b><progress max="${c.goal}" value="${progress}" aria-label="${c.name} progress"></progress></div><div class="contract-loot">◈ ${c.credits} CREDITS <span>◇ ${c.chips} STYLE</span></div><button class="${ready?'primary':'secondary'}" ${ready?'data-contract="'+c.id+'"':'data-contract-play'} ${claimed?'disabled':''}>${claimed?'✓ COLLECTED':ready?'COLLECT REWARD ↗':'DRIVE A ROUTE ↗'}</button></article>`}).join('')}</div><div class="section-title"><div><h3>DRIVING MILESTONES.</h3><p>Lifetime badges stay with your local Driver Passport.</p></div><span class="pill">${data.badges.length} / ${badges.length}</span></div><div class="badge-grid">${badges.map(b=>{const owned=data.badges.includes(b.id);return `<article class="badge-card ${owned?'earned':''}"><b>${owned?'✦':'◇'}</b><div><h4>${b.name}</h4><p>${owned?'EARNED · +50 XP / +15 STYLE':Math.min(b.goal,Math.floor(data.totals[b.key]))+' / '+b.goal+' '+(b.key==='drift'?'drift seconds':b.key==='peak'?'style chain':b.key==='clean'?'clean escapes':b.key==='perfects'?'perfect nitros':b.key)}</p></div></article>`}).join('')}</div><p id="passportNote" role="status">${note}</p><p class="passport-note">Local, unranked progression. Contract credit claims are once per UTC day on this save. Missing a day never removes earned rewards. Clean escape: finish with at least 75% hull.</p>`}
function style(){const selected=paints.find(p=>p.id===preview)||paints[1];return `<div class="style-hero"><div><div class="eyebrow">YOUR CAR. YOUR SIGNATURE.</div><h3>BUILT TO<br><em>BE REMEMBERED.</em></h3><p>Liveries change your look, never your speed, grip or hull.</p><span class="pill">◇ ${data.chips} EARNED STYLE TOKENS</span></div><div class="livery-preview" style="--paint:${selected.color};--accent:${selected.accent}"><div class="preview-road"></div><div class="preview-car ${selected.id==='stock'?'preview-stock':''}" style="background-position:${-(C.data?.selected||0)*64}px 0"><i></i><b></b><span></span></div><strong>${selected.name}</strong><small>LIVE STRIPE PREVIEW · ALL FIVE CARS</small></div></div><div class="section-title"><div><h3>YOUR EARNED COLLECTION.</h3><p>Unlock finishes through Driver XP or spend style tokens earned by driving.</p></div><span class="pill">${data.owned.length} / ${paints.length}</span></div><div class="paint-grid">${paints.map(p=>{const own=data.owned.includes(p.id),equipped=data.equipped===p.id;return `<article class="paint-card ${equipped?'equipped':''}"><button class="paint-swatch" data-preview="${p.id}" aria-label="Preview ${p.name}" style="--paint:${p.color};--accent:${p.accent}"><i></i></button><h4>${p.name}</h4><p>${equipped?'EQUIPPED':own?'OWNED':p.level?'UNLOCK AT DRIVER LEVEL '+p.level:'◇ '+p.cost+' STYLE TOKENS'}</p><button class="secondary" ${equipped||!own&&(!p.cost||data.chips<p.cost)?'disabled':''} ${own?'data-equip':'data-stylebuy'}="${p.id}">${equipped?'✓ EQUIPPED':own?'EQUIP':p.cost?'UNLOCK WITH STYLE':'KEEP DRIVING'}</button></article>`}).join('')}</div><section class="supporter-offer"><div class="supporter-art"><span>HOMEBOUND</span><b>SUPPORTER<br>COLLECTION.</b><div><i style="background:#f4c76e"></i><i style="background:#ed8bd2"></i><i style="background:#7cdeb2"></i></div></div><div><div class="eyebrow">OPTIONAL · ONE-TIME COSMETIC PACK</div><h3>A LITTLE MORE YOU.</h3><p>Planned collection: three exclusive stripe designs and a supporter badge. All cars, all worlds and every performance upgrade remain earnable.</p><ul><li>Permanent cosmetics, no subscription</li><li>No random crates or paid performance</li><li>No forced ads or energy timers</li></ul><p class="store-availability">${catalog?.price?'Google Play catalog price: '+catalog.price+'. ':''}${catalog?.message||'Paid packs are not on sale in this build. Google Play catalog and purchase verification must be configured before checkout can be enabled.'}</p><button class="secondary" data-store-check>CHECK GOOGLE PLAY AVAILABILITY</button><small>Prices are shown only when returned by Google Play. No external checkout in this WebView.</small></div></section><p id="passportNote" role="status">${note}</p>`}
function view(tab){day();return tab==='journal'?journal():style()}
function bind(root){const open=tab=>C.open(tab);root.querySelectorAll('[data-pass]').forEach(b=>b.onclick=()=>open(b.dataset.pass));root.querySelectorAll('[data-contract-play]').forEach(b=>b.onclick=()=>open('levels'));root.querySelectorAll('[data-contract]').forEach(b=>b.onclick=()=>{claim(b.dataset.contract);open('journal')});root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{preview=b.dataset.preview;open('style')});root.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{equip(b.dataset.equip);open('style')});root.querySelectorAll('[data-stylebuy]').forEach(b=>b.onclick=()=>{buy(b.dataset.stylebuy);open('style')});root.querySelector('[data-store-check]')?.addEventListener('click',()=>{if(window.RunroadStore){note='Checking Google Play…';window.RunroadStore.onmessage=e=>{try{receiveStore(JSON.parse(e.data))}catch{}};window.RunroadStore.postMessage(JSON.stringify({type:'catalog'}))}else note='Google Play checkout is available only in a configured Android store build. You can earn every free livery here.';open('style')})}
function receiveStore(data){if(!data||typeof data.message!=='string')return;const product=Array.isArray(data.products)?data.products.find(p=>p.id==='runroad_supporter_pack'&&typeof p.price==='string'):null;catalog={message:data.message.slice(0,300).replace(/[<>&"']/g,''),price:product?.price.slice(0,64).replace(/[<>&"']/g,'')};if(state==='hub')C.open('style')}
function drawLivery(g){if(data.equipped==='stock'||!solo())return;const p=equippedPaint;g.fillStyle=p.color;g.fillRect(-6,-30,4,15);g.fillRect(2,-30,4,15);g.fillRect(-6,19,4,10);g.fillRect(2,19,4,10);g.fillStyle=p.accent;g.fillRect(-1,-30,2,15);g.fillRect(-1,19,2,10)}
return{begin,finish,claim,equip,buy,home,view,bind,drawLivery,receiveStore,get data(){return data},get receipt(){return receipt},get level(){return level()}};
})();
